module cmd/ailang/testdata/verify_preflight/call_site_collapse

export pure func total(n: int) -> int
  ensures { result >= 0 }
{
  if n <= 0 then 0 else n + total(n - 1)
}

-- FALSE: total(a) - total(a + 1) == -(a + 1) for a >= 0
export pure func gap(a: int) -> int
  requires { a >= 0 }
  ensures { result == 0 }
{
  total(a) - total(a + 1)
}

