func (e *Elaborator) normalizeBinaryOp(binop *ast.BinaryOp) (core.CoreExpr, error) {
	// Short-circuit operators desugar to core.If so downstream phases
	// (evaluator, bytecode VM, SMT) inherit laziness from If lowering.
	// See design_docs/planned/v0_11_3/m-eval-short-circuit-bool.md.
	if binop.Op == "&&" || binop.Op == "||" {
		return e.normalizeShortCircuit(binop)
	}

// normalizeShortCircuit desugars `a && b` and `a || b` into core.If so that
// the right operand is only evaluated when needed:
//
//	a && b  =>  if a then b else false
//	a || b  =>  if a then true else b
//
// The LHS is normalized to atomic (ANF) so any complex subexpressions run
// exactly once before the branch. The RHS is normalized *without* forcing it
// to atomic — any let-bindings it would emit stay inside the lazy branch.
func (e *Elaborator) normalizeShortCircuit(binop *ast.BinaryOp) (core.CoreExpr, error) {
	left, leftBinds, err := e.normalizeToAtomic(binop.Left)
	if err != nil {
		return nil, err
	}

	right, err := e.normalize(binop.Right)
	if err != nil {
		return nil, err
	}

	node := e.makeNode(binop.Position())
	boolLit := func(v bool) core.CoreExpr {
		return &core.Lit{
			CoreNode: e.makeNode(binop.Position()),
			Kind:     core.BoolLit,
			Value:    v,
		}
	}

	var thenBranch, elseBranch core.CoreExpr
	switch binop.Op {
	case "&&":
		thenBranch = right
		elseBranch = boolLit(false)
	case "||":
		thenBranch = boolLit(true)
		elseBranch = right
	default:
		return nil, fmt.Errorf("normalizeShortCircuit called with non-short-circuit op %q", binop.Op)
	}

	result := &core.If{
		CoreNode: node,
		Cond:     left,
		Then:     thenBranch,
		Else:     elseBranch,
	}
	return e.wrapWithBindings(result, leftBinds), nil
}

// elaborateContracts elaborates contract properties to Core contracts.
// M-VERIFY: Contract expressions reference function parameters by name.
func (e *Elaborator) elaborateContracts(props []*ast.Property) ([]*core.Contract, error) {
	if len(props) == 0 {
		return nil, nil
	}

	var contracts []*core.Contract
	for _, prop := range props {
		// Only process requires/ensures contracts (skip forall properties)
		if prop.Kind != ast.RequiresKind && prop.Kind != ast.EnsuresKind && prop.Kind != ast.InvariantKind {
			continue
		}

		// Elaborate the predicate expression to Core
		coreExpr, err := e.elaborateExpr(prop.Expr)
		if err != nil {
			return nil, fmt.Errorf("elaborating contract: %w", err)
		}

		// Map AST kind to Core kind
		var kind core.ContractKind
		switch prop.Kind {
		case ast.RequiresKind:
			kind = core.RequiresKind
		case ast.EnsuresKind:
			kind = core.EnsuresKind
		case ast.InvariantKind:
			kind = core.InvariantKind
		}

		// Generate message from expression if not provided
		message := prop.Name
		if message == "" {
			message = prop.Expr.String()
		}

		// Format location
		location := fmt.Sprintf("%s:%d:%d", prop.Pos.File, prop.Pos.Line, prop.Pos.Column)

		contracts = append(contracts, &core.Contract{
			Kind:     kind,
			Expr:     coreExpr,
			Message:  message,
			Location: location,
		})
	}

	return contracts, nil
}

