// normalizeMatch handles pattern matching
func (e *Elaborator) normalizeMatch(match *ast.Match) (core.CoreExpr, error) {
	// Scrutinee must be atomic
	scrutinee, binds, err := e.normalizeToAtomic(match.Expr)
	if err != nil {
		return nil, err
	}

	// Convert arms
	var arms []core.MatchArm
	for _, caseClause := range match.Cases {
		pattern, err := e.elaboratePattern(caseClause.Pattern)
		if err != nil {
			return nil, err
		}

		// The pattern's binders are in scope for the guard and body (#1467).
		e.pushScope(corePatternBinders(pattern)...)
		body, guard, err := e.normalizeArm(caseClause)
		e.popScope()
		if err != nil {
			return nil, err
		}

		arms = append(arms, core.MatchArm{
			Pattern: pattern,
			Guard:   guard,
			Body:    body,
		})
	}

// normalizeArm normalizes a match arm's body and optional guard.
func (e *Elaborator) normalizeArm(caseClause *ast.Case) (body, guard core.CoreExpr, err error) {
	body, err = e.normalize(caseClause.Body)
	if err != nil {
		return nil, nil, err
	}
	if caseClause.Guard != nil {
		guard, err = e.normalize(caseClause.Guard)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to elaborate guard: %w", err)
		}
	}
	return body, guard, nil
}

// elaborateExpr transforms surface expression to Core ANF
func (e *Elaborator) elaborateExpr(expr ast.Expr) (core.CoreExpr, error) {
	// First pass: desugar surface constructs
	desugared := e.desugar(expr)

	// Second pass: normalize to ANF
	return e.normalize(desugared)
}

